//! adding a platform changeset (Solution 7 Phase 1, D-785, design §5.7).
//!
//! The platform changesets compiled into this binary, in folder order (the
//! order `changeset::boot::apply_platform_changesets` applies them in). Each
//! `name` is the platform bundle it was converted from (`scripts/changesets/
//! from-bundle.mjs`), which is how the boot path finds a bundle's changeset.

/// One compiled platform changeset.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PlatformChangeset {
    /// `NNNN-<name>.json`.
    pub file: &'static str,
    /// The changeset's `name` (the platform bundle it replaces).
    pub name: &'static str,
    /// The file content.
    pub json: &'static str,
}

