#[cfg(test)]
mod tests {
    use super::*;

    /// `PLATFORM_CHANGESETS` names every `changesets/platform/*.json`, once,
    /// in folder order.
    #[test]
    fn the_compiled_list_equals_the_folder() {
        let dir =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../changesets/platform");
        let mut on_disk: Vec<String> = std::fs::read_dir(&dir)
            .expect("changesets/platform/ is readable")
            .filter_map(|e| e.ok())
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|name| name.ends_with(".json"))
            .collect();
        on_disk.sort();
        let compiled: Vec<String> = PLATFORM_CHANGESETS
            .iter()
            .map(|c| c.file.to_owned())
            .collect();
        assert_eq!(compiled, on_disk);
    }
}
